-- Restore separate walking patrols for Stormwind officers.
-- Coverage checked against the corresponding Wowhead MoP Classic pin maps.
-- Jaxon uses the CMaNGOS classic-db street route with the disconnected old bank
-- interior detour omitted; the other routes come from the MoP reference data.
-- All consecutive segments, including loop closure, checked against MoP navigation data.
-- Retain existing AI, stealth-detection auras, equipment and combat settings.

-- Officer Jaxon (14423), spawn 31103, 105 points.
UPDATE creature SET position_x=-8818.35000, position_y=560.51400, position_z=94.52020,
    orientation=1.054738, MovementType=2, spawndist=0, currentwaypoint=0
WHERE guid=31103 AND id=14423;
DELETE FROM waypoint_data WHERE id=311030;
SELECT c.guid,311030,COALESCE(a.mount,0),COALESCE(a.bytes1,0),
    COALESCE(a.bytes2,0),COALESCE(a.emote,0),a.auras
FROM creature c LEFT JOIN creature_template_addon a ON a.entry=c.id
WHERE c.guid=31103 AND c.id=14423
ON DUPLICATE KEY UPDATE path_id=VALUES(path_id);

